// Kotlin Multiplatform: everything the interview does that has no platform
// surface, shared by the Android and iOS apps.
// The JS reference (src/*.js at the repo root) is the source of truth, and the
// golden fixtures in core/src/commonTest/resources/golden/ (generated by
// tools/golden/*.mjs) pin this port to it, run on the desktop JVM and (via
// :pdf and :core-device instrumented tests) under Android's ICU. Android
// modules consume the JVM variant, so their dependency lines are unchanged.
//
// The iOS targets are declared, but the iOS simulator run and the
// XCFramework build have not been verified: the sandbox this was written in
// is Linux, with no Xcode.
//
// On iOS the test binary has no bundle holding the test resources, so the
// tests read them from the host's disk (golden/TestPlatform.ios.kt).
// `syncIosTestResources` lays them out in core/build/ios-test-resources/
// (golden/, turn-scenarios/, fixtures/answers/), and the tests find that
// directory through GOLDEN_DIR, which simctl passes in with the SIMCTL_CHILD_
// prefix:
//   SIMCTL_CHILD_GOLDEN_DIR=$PWD/core/build/ios-test-resources ./gradlew :core:iosSimulatorArm64Test
// The main resources (schema.json, golden/metrics.json,
// golden/templateManifest.json) are read through the bundle, as in the app,
// so `copyIosTestBundleResources` puts them beside the test executable, which
// is where a bare executable's main bundle points.
plugins {
    alias(libs.plugins.kotlin.multiplatform)
}

// The interview schema is data, exported by the JS reference: the app loads
// the same file the goldens and the web app answer from. It is copied into
// build/, never into src/, so tools/schema.json stays the only copy anyone
// edits or commits.
val syncSchema = tasks.register<Copy>("syncSchema") {
    from("${rootProject.projectDir}/../tools/schema.json")
    into(layout.buildDirectory.dir("generated/schema-resources"))
}

// The turn scenarios are shared between the JS and Kotlin implementations;
// they are copied into the test resources pinned by hash, exactly like
// :pdf's forms and :speech's audio, so the Kotlin test runs the same files
// the turn golden was generated from. The answer fixtures feed the
// `resume` scenarios.
val syncScenarios = tasks.register<CopyPinnedAssets>("syncScenarios") {
    sourceDir = file("${rootProject.projectDir}/../tools/turn-scenarios")
    pins = file("turn-scenarios.SHA256SUMS")
    assetPath = "turn-scenarios"
    outputDir = layout.buildDirectory.dir("generated/scenario-resources/scenarios")
}

val syncFixtures = tasks.register<CopyPinnedAssets>("syncFixtures") {
    sourceDir = file("${rootProject.projectDir}/../tests/fixtures/answers")
    pins = file("answer-fixtures.SHA256SUMS")
    assetPath = "fixtures/answers"
    outputDir = layout.buildDirectory.dir("generated/scenario-resources/fixtures")
}

// See the iOS note at the top of this file.
val syncIosTestResources = tasks.register<Sync>("syncIosTestResources") {
    from("src/commonTest/resources")
    from(syncScenarios)
    from(syncFixtures)
    into(layout.buildDirectory.dir("ios-test-resources"))
}

val copyIosTestBundleResources = tasks.register<Copy>("copyIosTestBundleResources") {
    from("src/commonMain/resources")
    from(syncSchema)
    into(layout.buildDirectory.dir("bin/iosSimulatorArm64/debugTest"))
    mustRunAfter(tasks.matching { it.name == "linkDebugTestIosSimulatorArm64" })
}

tasks.matching { it.name == "iosSimulatorArm64Test" }.configureEach {
    dependsOn(syncIosTestResources, copyIosTestBundleResources)
}

kotlin {
    jvmToolchain(21)

    jvm()
    // Declared only; see the note at the top of this file.
    iosArm64()
    iosSimulatorArm64()

    sourceSets {
        commonMain {
            resources.srcDir(syncSchema)
            dependencies {
                implementation(libs.kotlinx.coroutines.core)
            }
        }
        commonTest {
            resources.srcDir(syncScenarios)
            resources.srcDir(syncFixtures)
            dependencies {
                implementation(kotlin("test"))
            }
        }
        jvmTest {
            dependencies {
                implementation(kotlin("test-junit"))
            }
        }
    }
}

tasks.named<Test>("jvmTest") {
    useJUnit()
    testLogging {
        events("failed", "skipped")
        showStackTraces = true
        exceptionFormat = org.gradle.api.tasks.testing.logging.TestExceptionFormat.FULL
    }
}
